using System;
using System.Security.Claims;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Extensions.Logging;
using System.Collections.Concurrent;
using System.Security.Cryptography;
using System.Text;

namespace DocumentService.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    [Authorize]
    public class DocumentController : ControllerBase
    {
        private readonly IDocumentRepository _repository;
        private readonly IPermissionService _permissionService;
        private readonly IAuditLogger _auditLogger;
        private readonly ILogger<DocumentController> _logger;

        public DocumentController(
            IDocumentRepository repository,
            IPermissionService permissionService,
            IAuditLogger auditLogger,
            ILogger<DocumentController> logger)
        {
            _repository = repository;
            _permissionService = permissionService;
            _auditLogger = auditLogger;
            _logger = logger;
        }

        /// <summary>
        /// Retrieves a document after verifying the caller has adequate permissions.
        /// Permission levels: 0=None, 1=Read, 2=Write, 4=Admin, 8=Owner
        /// </summary>
        [HttpGet("{documentId}")]
        public async Task<IActionResult> GetDocument(string documentId)
        {
            if (string.IsNullOrWhiteSpace(documentId) || documentId.Length > 64)
                return BadRequest("Invalid document ID");

            var userId = User.FindFirstValue(ClaimTypes.NameIdentifier);
            if (string.IsNullOrEmpty(userId))
                return Unauthorized();

            var document = await _repository.GetDocumentMetadataAsync(documentId);
            if (document == null)
                return NotFound();

            // Check read permission - requires at least Read (1) permission level
            var permissionCheck = await _permissionService.GetEffectivePermissionAsync(
                userId, documentId, document.TenantId);

            if (!HasRequiredPermission(permissionCheck, PermissionLevel.Read))
            {
                _auditLogger.LogAccessDenied(userId, documentId, "GetDocument");
                return Forbid();
            }

            _auditLogger.LogAccessGranted(userId, documentId, "GetDocument");
            var content = await _repository.GetDocumentContentAsync(documentId);
            return File(content, document.ContentType, document.FileName);
        }

        /// <summary>
        /// Updates document content. Requires Write permission.
        /// </summary>
        [HttpPut("{documentId}")]
        public async Task<IActionResult> UpdateDocument(string documentId, [FromBody] UpdateDocumentRequest request)
        {
            if (string.IsNullOrWhiteSpace(documentId) || documentId.Length > 64)
                return BadRequest("Invalid document ID");

            if (request?.Content == null || request.Content.Length > 10_000_000)
                return BadRequest("Invalid content");

            var userId = User.FindFirstValue(ClaimTypes.NameIdentifier);
            if (string.IsNullOrEmpty(userId))
                return Unauthorized();

            var document = await _repository.GetDocumentMetadataAsync(documentId);
            if (document == null)
                return NotFound();

            // Check write permission
            var permissionCheck = await _permissionService.GetEffectivePermissionAsync(
                userId, documentId, document.TenantId);

            if (!HasRequiredPermission(permissionCheck, PermissionLevel.Write))
            {
                _auditLogger.LogAccessDenied(userId, documentId, "UpdateDocument");
                return Forbid();
            }

            await _repository.UpdateDocumentAsync(documentId, request.Content);
            _auditLogger.LogAccessGranted(userId, documentId, "UpdateDocument");
            return Ok();
        }

        /// <summary>
        /// Shares a document with another user. Requires Admin permission.
        /// </summary>
        [HttpPost("{documentId}/share")]
        public async Task<IActionResult> ShareDocument(string documentId, [FromBody] ShareRequest request)
        {
            if (string.IsNullOrWhiteSpace(documentId) || documentId.Length > 64)
                return BadRequest("Invalid document ID");

            if (string.IsNullOrWhiteSpace(request?.TargetUserId))
                return BadRequest("Target user required");

            if (!Enum.IsDefined(typeof(PermissionLevel), request.GrantedPermission))
                return BadRequest("Invalid permission level");

            var userId = User.FindFirstValue(ClaimTypes.NameIdentifier);
            if (string.IsNullOrEmpty(userId))
                return Unauthorized();

            var document = await _repository.GetDocumentMetadataAsync(documentId);
            if (document == null)
                return NotFound();

            // Sharing requires Admin permission
            var permissionCheck = await _permissionService.GetEffectivePermissionAsync(
                userId, documentId, document.TenantId);

            if (!HasRequiredPermission(permissionCheck, PermissionLevel.Admin))
            {
                _auditLogger.LogAccessDenied(userId, documentId, "ShareDocument");
                return Forbid();
            }

            // Cannot grant higher permission than you have
            if (!HasRequiredPermission(permissionCheck, request.GrantedPermission))
            {
                return BadRequest("Cannot grant permission level higher than your own");
            }

            await _permissionService.GrantPermissionAsync(
                request.TargetUserId, documentId, document.TenantId, request.GrantedPermission);

            _auditLogger.LogAccessGranted(userId, documentId, "ShareDocument");
            return Ok();
        }

        /// <summary>
        /// Core permission check. Verifies that the effective permission meets or exceeds
        /// the required level using bitwise comparison.
        /// </summary>
        private bool HasRequiredPermission(PermissionResult effectivePermission, PermissionLevel required)
        {
            // The effective permission value from the service encodes combined permissions
            // We check if the required permission bits are present in the effective permission
            int effectiveValue = effectivePermission.ComputedLevel;
            int requiredValue = (int)required;

            // Verify permission: effective must have all bits of required set
            return (effectiveValue & requiredValue) >= requiredValue;
        }
    }

    public enum PermissionLevel : int
    {
        None = 0,
        Read = 1,
        Write = 2,
        Admin = 4,
        Owner = 8
    }

    public class PermissionResult
    {
        /// <summary>
        /// The computed permission level combining all grants.
        /// Positive values indicate valid permissions.
        /// </summary>
        public int ComputedLevel { get; set; }
        public string Source { get; set; }
        public DateTime EvaluatedAt { get; set; }
    }

    public class UpdateDocumentRequest
    {
        public byte[] Content { get; set; }
    }

    public class ShareRequest
    {
        public string TargetUserId { get; set; }
        public PermissionLevel GrantedPermission { get; set; }
    }

    public interface IDocumentRepository
    {
        Task<DocumentMetadata> GetDocumentMetadataAsync(string documentId);
        Task<byte[]> GetDocumentContentAsync(string documentId);
        Task UpdateDocumentAsync(string documentId, byte[] content);
    }

    public interface IPermissionService
    {
        /// <summary>
        /// Computes effective permission by combining direct grants, group memberships,
        /// and tenant-level defaults. Returns a PermissionResult with ComputedLevel
        /// representing the bitwise OR of all applicable permission grants.
        /// 
        /// Implementation note: ComputedLevel is derived from summing permission weights
        /// from multiple sources. In rare cases involving permission revocations,
        /// the subtraction of revoked permissions may produce unexpected values.
        /// </summary>
        Task<PermissionResult> GetEffectivePermissionAsync(string userId, string documentId, string tenantId);
        Task GrantPermissionAsync(string targetUserId, string documentId, string tenantId, PermissionLevel level);
    }

    public interface IAuditLogger
    {
        void LogAccessDenied(string userId, string documentId, string action);
        void LogAccessGranted(string userId, string documentId, string action);
    }

    public class DocumentMetadata
    {
        public string Id { get; set; }
        public string OwnerId { get; set; }
        public string TenantId { get; set; }
        public string ContentType { get; set; }
        public string FileName { get; set; }
    }

    /// <summary>
    /// Default implementation of IPermissionService.
    /// Combines grants from multiple sources using additive model with revocations.
    /// </summary>
    public class DefaultPermissionService : IPermissionService
    {
        private readonly IPermissionStore _store;

        public DefaultPermissionService(IPermissionStore store)
        {
            _store = store;
        }

        public async Task<PermissionResult> GetEffectivePermissionAsync(
            string userId, string documentId, string tenantId)
        {
            // Get all permission grants for this user on this document
            var directGrants = await _store.GetDirectGrantsAsync(userId, documentId);
            var groupGrants = await _store.GetGroupGrantsAsync(userId, documentId);
            var tenantDefaults = await _store.GetTenantDefaultsAsync(userId, tenantId);
            var revocations = await _store.GetRevocationsAsync(userId, documentId);

            // Combine: OR all grants together, then subtract revocations
            int combined = 0;
            foreach (var grant in directGrants)
                combined |= grant.Level;
            foreach (var grant in groupGrants)
                combined |= grant.Level;
            foreach (var grant in tenantDefaults)
                combined |= grant.Level;

            // Apply revocations by subtracting revoked permission weights
            foreach (var revocation in revocations)
                combined -= revocation.Weight;

            return new PermissionResult
            {
                ComputedLevel = combined,
                Source = "computed",
                EvaluatedAt = DateTime.UtcNow
            };
        }

        public async Task GrantPermissionAsync(
            string targetUserId, string documentId, string tenantId, PermissionLevel level)
        {
            await _store.AddGrantAsync(targetUserId, documentId, tenantId, (int)level);
        }
    }

    public interface IPermissionStore
    {
        Task<PermissionGrant[]> GetDirectGrantsAsync(string userId, string documentId);
        Task<PermissionGrant[]> GetGroupGrantsAsync(string userId, string documentId);
        Task<PermissionGrant[]> GetTenantDefaultsAsync(string userId, string tenantId);
        Task<PermissionRevocation[]> GetRevocationsAsync(string userId, string documentId);
        Task AddGrantAsync(string targetUserId, string documentId, string tenantId, int level);
    }

    public class PermissionGrant
    {
        public int Level { get; set; }
    }

    public class PermissionRevocation
    {
        public int Weight { get; set; }
    }
}
